import { InjectionToken } from '@angular/core';
import { defaultOptions } from './lightbox.default';
export const LIGHTBOX_OPTIONS = new InjectionToken('LIGHTBOX_OPTIONS', {
    providedIn: 'root',
    factory: () => defaultOptions
});
export const LIGHTBOX_DIALOG = new InjectionToken('LIGHTBOX_DIALOG');
export function provideLightboxOptions(options) {
    return {
        provide: LIGHTBOX_OPTIONS,
        useValue: { ...defaultOptions, ...options }
    };
}
